import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const dbPath = process.env.DB_PATH || 'data/workboard.sqlite';
mkdirSync(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
db.exec(`PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
);
CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id);`);
const listTasks = db.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY id');
const getProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, character => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} — Workboard</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; font-family: system-ui, sans-serif; background: #f4f6fa; color: #172338; }
    main { max-width: 760px; margin: 48px auto; padding: 24px; }
    h1 { overflow-wrap: anywhere; }
    form { display: flex; flex-wrap: wrap; align-items: end; gap: 12px; }
    label { display: grid; gap: 6px; flex: 1; min-width: 180px; font-weight: 600; }
    input, select, button { font: inherit; border-radius: 6px; padding: 10px 14px; }
    input { width: 100%; border: 1px solid #68768b; background: white; }
    button { border: 1px solid #224ea0; background: #224ea0; color: white; cursor: pointer; }
    :focus-visible { outline: 3px solid #c06400; outline-offset: 3px; }
    ul { list-style: none; padding: 0; margin-top: 24px; }
    li { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px; margin: 12px 0; background: white; border: 1px solid #cbd2de; border-radius: 8px; }
    li span { overflow-wrap: anywhere; min-width: 0; }
    li form { flex-shrink: 0; }
    input[type="checkbox"] { width: auto; }
    .task-label { display: flex; align-items: center; min-width: 0; overflow-wrap: anywhere; }
    [role="alert"] { color: #9e1c1c; font-weight: 600; }
  </style>
</head>
<body><main>${content}</main></body>
</html>`;
}

function html(response, status, title, content) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  response.end(page(title, content));
}

function projectsPage(response, error = '') {
  const projects = listProjects.all();
  html(response, 200, 'Projects', `
    <h1>Workboard</h1>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form method="post" action="/projects">
      <label for="project-name">Project name<input id="project-name" name="name" type="text"></label>
      <button type="submit">Create project</button>
    </form>
    <ul aria-label="Projects">${projects.map(project => `
      <li data-testid="project-row">
        <span>${escapeHtml(project.name)}</span>
        <form method="get" action="/projects/${project.id}"><button type="submit">Open project</button></form>
      </li>`).join('')}</ul>
    ${projects.length ? '' : '<p>No projects yet.</p>'}`);
}

function taskFilter(value) {
  return ['all', 'open', 'completed'].includes(value) ? value : 'all';
}

function projectPage(response, project, filter = 'all', error = '') {
  const tasks = listTasks.all(project.id).filter(task =>
    filter === 'all' || Boolean(task.completed) === (filter === 'completed'));
  const path = `/projects/${project.id}`;
  html(response, 200, project.name, `
    <h1>${escapeHtml(project.name)}</h1>
    <form method="get" action="/"><button type="submit">Projects</button></form>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form method="post" action="${path}/tasks">
      <input type="hidden" name="filter" value="${filter}">
      <label for="task-title">Task title<input id="task-title" name="title" type="text"></label>
      <button type="submit">Create task</button>
    </form>
    <form method="get" action="${path}">
      <label for="task-filter">Task filter
        <select id="task-filter" name="filter" onchange="this.form.requestSubmit()">
          ${[['all', 'All'], ['open', 'Open'], ['completed', 'Completed']].map(([value, label]) =>
            `<option value="${value}"${filter === value ? ' selected' : ''}>${label}</option>`).join('')}
        </select>
      </label>
      <noscript><button type="submit">Apply filter</button></noscript>
    </form>
    <ul aria-label="Tasks">${tasks.map(task => `
      <li data-testid="task-row">
        <form method="post" action="${path}/tasks/${task.id}">
          <input type="hidden" name="filter" value="${filter}">
          <label class="task-label">
            <input type="checkbox" name="completed" value="1"
              aria-label="Complete ${escapeHtml(task.title)}"${task.completed ? ' checked' : ''}
              onchange="saveCompletion(this)">
            <span>${escapeHtml(task.title)}</span>
          </label>
          <noscript><button type="submit">Save completion</button></noscript>
        </form>
      </li>`).join('')}</ul>
    ${tasks.length ? '' : '<p>No matching tasks.</p>'}
    <p id="completion-error" role="alert" hidden>Unable to save completion. Please try again.</p>
    <script>
      function saveCompletion(checkbox) {
        const form = checkbox.form;
        const error = document.getElementById('completion-error');
        error.hidden = true;
        try {
          // Finish the small local save before a reload can cancel it.
          const request = new XMLHttpRequest();
          request.open('POST', form.action, false);
          request.setRequestHeader('Accept', 'application/json');
          request.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
          request.send(new URLSearchParams(new FormData(form)).toString());
          if (request.status !== 204) throw new Error('Save failed');
          const filter = form.elements.filter.value;
          if ((filter === 'open' && checkbox.checked) ||
              (filter === 'completed' && !checkbox.checked)) {
            checkbox.closest('[data-testid="task-row"]').remove();
          }
        } catch {
          checkbox.checked = !checkbox.checked;
          error.hidden = false;
        }
      }
    </script>`);
}

async function readForm(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      const error = new Error('Request too large');
      error.status = 413;
      throw error;
    }
  }
  return new URLSearchParams(body);
}

const server = http.createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    if (request.method === 'GET' && url.pathname === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ status: 'ok' }));
    } else if (request.method === 'GET' && url.pathname === '/') {
      projectsPage(response);
    } else if (request.method === 'POST' && url.pathname === '/projects') {
      const form = await readForm(request);
      const name = (form.get('name') || '').trim();
      if (!name) {
        projectsPage(response, 'Project name is required');
        return;
      }
      createProject.run(name);
      response.writeHead(303, { Location: '/' });
      response.end();
    } else if (request.method === 'GET' && /^\/projects\/\d+$/.test(url.pathname)) {
      const project = getProject.get(Number(url.pathname.split('/')[2]));
      if (!project) {
        html(response, 404, 'Not found', '<h1>Project not found</h1><form action="/"><button>Projects</button></form>');
        return;
      }
      projectPage(response, project, taskFilter(url.searchParams.get('filter')));
    } else if (request.method === 'POST' && /^\/projects\/\d+\/tasks(?:\/\d+)?$/.test(url.pathname)) {
      const [, , projectId, , taskId] = url.pathname.split('/');
      const project = getProject.get(Number(projectId));
      if (!project) {
        html(response, 404, 'Not found', '<h1>Project not found</h1>');
        return;
      }
      const form = await readForm(request);
      const filter = taskFilter(form.get('filter'));
      if (taskId) {
        const result = updateTask.run(form.get('completed') === '1' ? 1 : 0, Number(taskId), project.id);
        if (!result.changes) {
          html(response, 404, 'Not found', '<h1>Task not found</h1>');
          return;
        }
      } else {
        const title = (form.get('title') || '').trim();
        if (!title) {
          projectPage(response, project, filter, 'Task title is required');
          return;
        }
        createTask.run(project.id, title);
      }
      if (taskId && request.headers.accept === 'application/json') {
        response.writeHead(204);
        response.end();
        return;
      }
      response.writeHead(303, { Location: `/projects/${project.id}?filter=${filter}` });
      response.end();
    } else {
      html(response, 404, 'Not found', '<h1>Page not found</h1>');
    }
  } catch (error) {
    console.error(error);
    html(response, error.status || 500, 'Error', '<h1>Unable to process request</h1>');
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => server.close(() => {
    db.close();
    process.exit(0);
  }));
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import net from 'node:net';
import { runInNewContext } from 'node:vm';

async function unusedPort() {
  const socket = net.createServer();
  await new Promise(resolve => socket.listen(0, '127.0.0.1', resolve));
  const port = socket.address().port;
  await new Promise(resolve => socket.close(resolve));
  return port;
}

test('projects validate, preserve order, open and persist across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const port = await unusedPort();
  const base = `http://127.0.0.1:${port}`;
  let child;
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'projects.sqlite') },
      stdio: ['ignore', 'ignore', 'pipe'],
    });
    let errors = '';
    child.stderr.on('data', chunk => { errors += chunk; });
    for (let attempt = 0; attempt < 100; attempt++) {
      if (child.exitCode !== null) throw new Error(`Server exited: ${errors}`);
      try {
        const response = await fetch(`${base}/health`);
        assert.equal(response.status, 200);
        assert.deepEqual(await response.json(), { status: 'ok' });
        return;
      } catch {
        await new Promise(resolve => setTimeout(resolve, 30));
      }
    }
    throw new Error(`Server did not start: ${errors}`);
  }
  async function stop() {
    if (child && child.exitCode === null) {
      const exited = new Promise(resolve => child.once('exit', resolve));
      child.kill('SIGTERM');
      await exited;
    }
  }
  async function create(name) {
    return fetch(`${base}/projects`, {
      method: 'POST', body: new URLSearchParams({ name }), redirect: 'manual',
    });
  }
  try {
    await start();
    let content = await (await fetch(base)).text();
    assert.match(content, /<h1>Workboard<\/h1>/);
    assert.match(content, /Project name<input/);
    assert.match(content, />Create project<\/button>/);
    assert.doesNotMatch(content, /data-testid="project-row"/);
    for (const name of ['', '   ']) {
      content = await (await create(name)).text();
      assert.match(content, /role="alert">Project name is required/);
      assert.doesNotMatch(content, /data-testid="project-row"/);
    }
    assert.equal((await create('  First project  ')).status, 303);
    assert.equal((await create('Second <project>')).status, 303);
    content = await (await fetch(base)).text();
    assert.equal((content.match(/data-testid="project-row"/g) || []).length, 2);
    assert.match(content, /<span>First project<\/span>/);
    assert.ok(content.indexOf('First project') < content.indexOf('Second &lt;project&gt;'));
    const paths = [...content.matchAll(/action="(\/projects\/\d+)"/g)].map(match => match[1]);
    assert.equal(paths.length, 2);
    let detail = await (await fetch(base + paths[0])).text();
    assert.match(detail, /<h1>First project<\/h1>/);
    assert.match(detail, /action="\/".*>Projects<\/button>/);
    assert.equal((await fetch(`${base}/projects/9999`)).status, 404);
    const projectPath = paths[0];
    async function postTask(path, values) {
      return fetch(base + path, {
        method: 'POST', body: new URLSearchParams(values), redirect: 'manual',
      });
    }
    const taskRows = html => [...html.matchAll(/<li data-testid="task-row">([\s\S]*?)<\/li>/g)].map(match => match[1]);
    assert.match(detail, /Task title<input/);
    assert.match(detail, /<option value="all" selected>All/);
    for (const title of ['', '   ']) {
      const invalid = await (await postTask(`${projectPath}/tasks`, { title })).text();
      assert.match(invalid, /role="alert">Task title is required/);
      assert.equal(taskRows(invalid).length, 0);
    }
    assert.equal((await postTask(`${projectPath}/tasks`, { title: '  First task  ' })).status, 303);
    assert.equal((await postTask(`${projectPath}/tasks`, { title: 'Second <task>' })).status, 303);
    detail = await (await fetch(base + projectPath)).text();
    let rows = taskRows(detail);
    assert.equal(rows.length, 2);
    assert.match(rows[0], /<span>First task<\/span>/);
    assert.match(rows[0], /aria-label="Complete First task"/);
    assert.match(rows[1], /Second &lt;task&gt;/);
    assert.ok(rows.every(row => !row.includes(' checked')));
    const taskPath = rows[0].match(/action="([^"]+)"/)[1];
    assert.equal((await postTask(taskPath, { completed: '1' })).status, 303);
    rows = taskRows(await (await fetch(`${base}${projectPath}?filter=completed`)).text());
    assert.equal(rows.length, 1);
    assert.match(rows[0], / checked/);
    assert.match(rows[0], /First task/);
    rows = taskRows(await (await fetch(`${base}${projectPath}?filter=open`)).text());
    assert.equal(rows.length, 1);
    assert.match(rows[0], /Second &lt;task&gt;/);
    assert.equal(taskRows(await (await fetch(base + paths[1])).text()).length, 0);
    const foreignTaskPath = taskPath.replace(projectPath, paths[1]);
    assert.equal((await postTask(foreignTaskPath, {})).status, 404);
    detail = await (await fetch(base + projectPath)).text();
    await stop();
    await start();
    assert.equal(await (await fetch(base)).text(), content);
    assert.equal(await (await fetch(base + paths[0])).text(), detail);
    assert.equal((await postTask(taskPath, {})).status, 303);
    rows = taskRows(await (await fetch(base + projectPath)).text());
    assert.ok(rows.every(row => !row.includes(' checked')));
    assert.equal(taskRows(await (await fetch(`${base}${projectPath}?filter=completed`)).text()).length, 0);

    // Exercise the browser change handler, including the immediate-reload case.
    const script = detail.match(/<script>([\s\S]*?)<\/script>/)[1];
    for (const completed of [true, false]) {
      let savedRequest;
      const error = { hidden: true };
      const checkbox = {
        checked: completed,
        form: { action: base + taskPath, elements: { filter: { value: 'all' } } },
      };
      const context = {
        document: { getElementById: () => error },
        URLSearchParams,
        FormData: class {
          constructor() {
            return completed ? [['filter', 'all'], ['completed', '1']] : [['filter', 'all']];
          }
        },
        XMLHttpRequest: class {
          open(method, url, asynchronous) {
            assert.equal(asynchronous, false, 'save must finish before change returns');
            savedRequest = { method, url, headers: {} };
          }
          setRequestHeader(name, value) { savedRequest.headers[name] = value; }
          send(body) { savedRequest.body = body; this.status = 204; }
        },
      };
      runInNewContext(script, context);
      context.saveCompletion(checkbox);
      assert.equal(error.hidden, true);
      const { url, ...options } = savedRequest;
      assert.equal((await fetch(url, options)).status, 204);
      const reloaded = taskRows(await (await fetch(base + projectPath)).text());
      assert.equal(reloaded[0].includes(' checked'), completed);
      await stop();
      await start();
      assert.equal(taskRows(await (await fetch(base + projectPath)).text())[0].includes(' checked'), completed);
    }
  } finally {
    await stop();
    await rm(directory, { recursive: true, force: true });
  }
});

